=== README.md
# billing-events

Subscription lifecycle for the billing service. Everything that happens to a subscription is a
`SubscriptionEvent` (`src/events.ts`), and three places consume those events:

- `src/subscription.ts` rebuilds a subscription's current state from its events.
- `src/audit.ts` turns an event into one line for the audit log.
- `src/notifier.ts` decides which emails an event triggers.

Each of them ends its `switch` with `assertNever`, so the compiler tells you where a new event type still
needs handling.

## Setup and tests

```
npm install
npm test            # node --test
npm run typecheck   # tsc --noEmit
```
=== src/assert-never.ts
/** Makes a `switch` over a union exhaustive: the compiler rejects the call while a case is still unhandled. */
export function assertNever(value: never): never {
  throw new Error(`Unhandled value: ${JSON.stringify(value)}`);
}
=== src/audit.ts
import { assertNever } from "./assert-never.ts";
import type { SubscriptionEvent } from "./events.ts";

/** One line for the audit log: timestamp, subscription id, event type, then the event's details. */
export function serializeAuditEntry(event: SubscriptionEvent): string {
  const entry = `${event.occurredAt} ${event.subscriptionId} ${event.type}`;
  const details = auditDetails(event);
  return details === "" ? entry : `${entry} ${details}`;
}

function auditDetails(event: SubscriptionEvent): string {
  switch (event.type) {
    case "subscription_started":
      return `plan=${event.plan}`;
    case "plan_changed":
      return `from=${event.from} to=${event.to}`;
    case "payment_failed":
      return `attempt=${event.attempt}`;
    case "payment_recovered":
      return "";
    case "subscription_canceled":
      return `reason=${JSON.stringify(event.reason)}`;
    default:
      return assertNever(event);
  }
}
=== src/events.ts
export type Plan = "basic" | "pro" | "enterprise";

interface EventBase {
  subscriptionId: string;
  /** When it happened, as an ISO 8601 timestamp in UTC. */
  occurredAt: string;
}

export interface SubscriptionStarted extends EventBase {
  type: "subscription_started";
  plan: Plan;
}

export interface PlanChanged extends EventBase {
  type: "plan_changed";
  from: Plan;
  to: Plan;
}

export interface PaymentFailed extends EventBase {
  type: "payment_failed";
  /** 1 for the first failed charge, 2 for the retry after it, and so on. */
  attempt: number;
}

export interface PaymentRecovered extends EventBase {
  type: "payment_recovered";
}

export interface SubscriptionCanceled extends EventBase {
  type: "subscription_canceled";
  reason: string;
}

export type SubscriptionEvent =
  | SubscriptionStarted
  | PlanChanged
  | PaymentFailed
  | PaymentRecovered
  | SubscriptionCanceled;
=== src/index.ts
export { serializeAuditEntry } from "./audit.ts";
export type { Plan, SubscriptionEvent } from "./events.ts";
export { notificationsFor } from "./notifier.ts";
export type { Notification } from "./notifier.ts";
export { reduceSubscription, replay } from "./subscription.ts";
export type { Subscription, SubscriptionStatus } from "./subscription.ts";
=== src/notifier.ts
import { assertNever } from "./assert-never.ts";
import type { PaymentFailed, SubscriptionEvent } from "./events.ts";

export interface Notification {
  audience: "customer" | "billing-team";
  template: string;
  data: Record<string, string>;
}

/** After this many failed charges the billing team steps in. */
const ESCALATION_ATTEMPT = 3;

/** The emails an event triggers, in the order they are sent. */
export function notificationsFor(event: SubscriptionEvent): Notification[] {
  switch (event.type) {
    case "subscription_started":
      return [{ audience: "customer", template: "welcome", data: { plan: event.plan } }];
    case "plan_changed":
      return [{ audience: "customer", template: "plan-changed", data: { from: event.from, to: event.to } }];
    case "payment_failed":
      return paymentFailedNotifications(event);
    case "payment_recovered":
      return [];
    case "subscription_canceled":
      return [{ audience: "customer", template: "subscription-canceled", data: { reason: event.reason } }];
    default:
      return assertNever(event);
  }
}

function paymentFailedNotifications(event: PaymentFailed): Notification[] {
  const data = { attempt: String(event.attempt) };
  const notifications: Notification[] = [{ audience: "customer", template: "payment-failed", data }];
  if (event.attempt >= ESCALATION_ATTEMPT) {
    notifications.push({ audience: "billing-team", template: "payment-escalation", data });
  }
  return notifications;
}
=== src/subscription.ts
import { assertNever } from "./assert-never.ts";
import type { Plan, SubscriptionEvent, SubscriptionStarted } from "./events.ts";

export type SubscriptionStatus = "active" | "past_due" | "canceled";

export interface Subscription {
  id: string;
  plan: Plan;
  status: SubscriptionStatus;
  /** The attempt number of the latest failed charge; 0 while payments are fine. */
  failedAttempts: number;
  startedAt: string;
  canceledAt: string | null;
}

/** The state of a subscription after all of its events, oldest first. The first event must be the start. */
export function replay(events: readonly SubscriptionEvent[]): Subscription {
  const [first, ...rest] = events;
  if (first?.type !== "subscription_started") {
    throw new Error("A subscription history starts with subscription_started");
  }
  return rest.reduce(reduceSubscription, startedSubscription(first));
}

export function reduceSubscription(state: Subscription, event: SubscriptionEvent): Subscription {
  switch (event.type) {
    case "subscription_started":
      // A repeated start event changes nothing.
      return state;
    case "plan_changed":
      return { ...state, plan: event.to };
    case "payment_failed":
      if (state.status === "canceled") {
        return state;
      }
      return { ...state, status: "past_due", failedAttempts: event.attempt };
    case "payment_recovered":
      if (state.status !== "past_due") {
        return state;
      }
      return { ...state, status: "active", failedAttempts: 0 };
    case "subscription_canceled":
      if (state.status === "canceled") {
        return state;
      }
      return { ...state, status: "canceled", canceledAt: event.occurredAt };
    default:
      return assertNever(event);
  }
}

function startedSubscription(event: SubscriptionStarted): Subscription {
  return {
    id: event.subscriptionId,
    plan: event.plan,
    status: "active",
    failedAttempts: 0,
    startedAt: event.occurredAt,
    canceledAt: null,
  };
}
